function sharedWeekSelector(){
 const w=currentSharedWeek()?.week||1,max=Math.max(1,+S.cfg?.weeks||12);
 return `<div class=row><select id=sharedWeekChoice aria-label="Current attendance week">${rng(max).map(i=>`<option value="${i}" ${i===w?'selected':''}>Week ${i}</option>`).join('')}</select><button onclick=setSharedAttendanceWeek()>Set shared week</button></div>`;
}
function changeDeviceCache(enable){if(enable&&!confirm('Only enable stored offline student data on your own trusted, locked device. The browser will retain student records after you close LabTrack. Continue?')){render();return}localStorage.setItem('labtrack-device-cache',enable?'1':'0');if(!enable)localStorage.setItem('labtrack-clear-cache','1');location.reload()}
function vSet(){const c=S.cfg,T={in:'Score',att:'Attendance',grp:'Group',sum:'Sum'},nm=k=>c.items.find(i=>i.k===k)?.n;
 const desc=i=>i.t=='att'?(i.mode==='none'?'Attendance does not add a grade':i.mode==='bands'?`Attendance bands (${(i.bandRules||[]).length} rules)` :i.mode=='pen'?`max minus ${i.pen} per absence`:'attended / weeks x max'):i.t=='grp'?`${i.agg=='avg'?'average':'sum'} of ${i.top?'highest '+i.top+' of ':''}${(i.src||[]).map(nm).join(', ')}${i.mul!=1?' x '+i.mul:''}`:i.t=='sum'?(i.src||[]).map(nm).join(' + '):'';
 return `<div class=card><h3>Course settings</h3>${S.admin?'':'<p class=m>Only the admin can change grading structure and lock weeks.</p>'}
<label>Number of weeks<input type=number min=1 max=30 ${S.admin?'':'disabled'} value="${c.weeks}" onchange="Cf().update({weeks:+this.value||12})"></label></div>
<div class=card><h3>Shared attendance week (Firebase)</h3><p class=m>${currentSharedWeek()?`Current default: <b>Week ${currentSharedWeek().week}</b>. Every approved instructor receives this same default. On Friday (Cairo time), the shared default advances by one week, never past Week ${c.weeks}.`:'Not configured yet. An administrator must choose the actual current week before attendance entry is enabled.'} An instructor can visit an earlier week without changing everyone else's default; their choice is saved to their own Firebase session, and the next shared-week advance restores the new default.</p>${S.admin?sharedWeekSelector():'<span class=badge>Only the administrator can reset the default</span>'}</div>
<div class=card><h3>Attendance policy</h3><p class=m>These two values can be adjusted by any signed-in instructor.</p>
<label>Other-lab attendance allowance per student<input type=number min=0 max=30 value="${c.altLabLimit??2}" onchange="Cf().set({altLabLimit:Math.max(0,+this.value||0)},{merge:true})"></label>
<label>Absence warning threshold <span class=m>(warning appears after the student exceeds this number)</span><input type=number min=0 max=30 value="${c.absenceWarn??3}" onchange="Cf().set({absenceWarn:Math.max(0,+this.value||0)},{merge:true})"></label></div>
<div class=card><h3>Grading items</h3>${c.items.map(i=>`<div class=row><div style="flex:1"><b>${esc(i.n)}</b> <span class=m>${T[i.t]}, max ${i.max}<br>${esc(desc(i))}</span></div>${S.admin?`<button class=g onclick="editItem('${i.k}')">Edit</button><button class=d onclick="delItem('${i.k}')">&#10005;</button>`:''}</div>`).join('')}
${S.admin?`<div class=row><button onclick="editItem('','in')">Add score</button><button onclick="editItem('','grp')">Add group</button><button onclick="editItem('','sum')">Add sum</button></div>
<p class=m>Group: choose assessments and a calculation preset (or a custom highest-N, average/sum and multiplier). Sum: add any items together, including groups and other sums.</p>`:''}</div><div class=card><h3>Firebase read optimization & compact directory</h3><p class=m>Attendance listens only to the active lab and week’s visitors. Automatic all-lab search and visiting-student selection use a lightweight directory containing only serial, student ID, name and assigned lab (16 Firebase shards). The selected visitor’s live student record is fetched before marking attendance. Full exports and All Labs grading still fetch complete student records.</p><p class=m><b>Directory status:</b> ${esc(directoryReady?'Ready · '+directoryRows.length+' students':directoryStatus+(directoryError?' · '+directoryError:''))}. An administrator can rebuild the index after bulk imports or if a synchronization warning occurs.</p><div class=row>${S.admin?'<button onclick=buildStudentDirectory()>Rebuild compact directory</button>':''}<button class=g onclick=downloadCompactDirectory()>Download compact roster (Excel)</button></div><label class=ck><input type=checkbox ${localStorage.getItem('labtrack-device-cache')==='1'?'checked':''} onchange="changeDeviceCache(this.checked)">Keep an offline Firestore cache on this trusted device</label><p class=m>Optional. Turn this on only on a private locked device. Turning it off attempts to clear previously stored student data. Browser cache may reduce repeated reconnect reads, but Firebase billing depends on server activity.${cacheWarning?' '+esc(cacheWarning):''}</p></div><div class=card><h3>Student data & backups</h3><p class=m>Export every student from every lab, including attendance and visiting-lab records, scores, and student notes. Excel is a readable table; JSON keeps original document IDs and complete data for a future restore. These exports do not modify Firebase.</p><div class=row><button onclick=openExamAttendanceExport()>Exam attendance sheets · by lab</button><button onclick=exAllStudentsExcel()>Export all students · Excel</button><button class=g onclick=exAllStudentsJson()>Download JSON backup</button></div></div>${tplCards(c)}${securityCard()}`}

function bandRow(r={},idx=0){return `<div class="row band-row" style="border-top:1px solid var(--b);padding-top:6px"><label>Condition<select class=band-op><option value="&lt;=" ${r.op==='<='?'selected':''}>≤</option><option value="=" ${r.op==='='?'selected':''}>=</option><option value="&gt;=" ${r.op==='>='?'selected':''}>≥</option></select></label><label>Count<input class=band-n type=number min=0 value="${esc(r.n??0)}" style="width:90px"></label><label>Grade<input class=band-grade type=number min=0 step=.25 value="${esc(r.grade??0)}" style="width:90px"></label><button type=button class=d onclick="this.closest('.band-row').remove()">Remove</button></div>`}
function addBandRow(){const div=document.createElement('div');div.innerHTML=bandRow({op:'<=',n:0,grade:0});$('#bandRows')?.appendChild(div.firstElementChild)}

function editItem(k,t){const i=k?{...S.cfg.items.find(x=>x.k===k)}:{k:'c'+Date.now(),t,n:'',max:10,src:[],top:0,agg:'avg',mul:1,mode:'ratio',pen:1},o=S.cfg.items.filter(x=>x.k!==i.k),sel=(a,b)=>a==b?'selected':'';
 $('#modal').innerHTML=`<div class=ov><div class=card><h3>${k?'Edit':'New'} item</h3>
<label>Name<input id=m_n value="${esc(i.n)}"></label><label>Max grade<input id=m_max type=number step=any value="${i.max}"></label>
${i.t=='att'?`<label>Rule<select id=m_mode><option value=ratio ${sel(i.mode,'ratio')}>Attended / weeks x max</option><option value=pen ${sel(i.mode,'pen')}>Max minus marks per absence</option><option value=bands ${sel(i.mode,'bands')}>Grade bands (rules)</option><option value=none ${sel(i.mode,'none')}>No attendance grade</option></select></label><label>Marks lost per absence<input id=m_pen type=number step=any value="${i.pen}"></label><p class=m>For grade bands, the first matching rule determines the grade. If none matches, it is 0.</p><label>Grade bands based on<select id=m_bandBasis><option value=absent ${sel(i.bandBasis||'absent','absent')}>Absences</option><option value=attended ${sel(i.bandBasis||'absent','attended')}>Attended sessions</option></select></label><div id=bandRows>${(i.bandRules||[]).map((r,idx)=>bandRow(r,idx)).join('')}</div><button type=button class=g onclick=addBandRow()>+ Add grade band</button>`:''}
${i.t=='grp'||i.t=='sum'?`<p class=m>Use these items:</p>${o.map(x=>`<label class=ck><input type=checkbox value="${x.k}" ${(i.src||[]).includes(x.k)?'checked':''}>${esc(x.n)}</label>`).join('')}`:''}
${i.t=='grp'?`<label>Calculation preset<select id=m_preset><option value=custom ${sel(i.preset||'custom','custom')}>Custom average / sum</option>${[['highest','Highest score'],['highest_half','Highest score ÷ 2'],['avg_all','Average of all'],['avg_high2','Average of highest two'],['sum_high2','Sum of highest two'],['sum_all','Sum of all']].map(([key,name])=>`<option value="${key}" ${sel(i.preset,key)}>${name}</option>`).join('')}</select></label><label>Highest N only (0 = all)<input id=m_top type=number value="${i.top}"></label><label>Combine by<select id=m_agg><option value=avg ${sel(i.agg,'avg')}>Average</option><option value=sum ${sel(i.agg,'sum')}>Sum</option></select></label><label>Multiply result by<input id=m_mul type=number step=any value="${i.mul}"></label>`:''}
<div class=row><button onclick="saveItem('${i.k}','${i.t}')">Save item</button><button class=g onclick="$('#modal').innerHTML=''">Cancel</button></div></div></div>`}

function gradeItemDependencyCycle(items){const by=new Map(items.map(i=>[i.k,i])),state=new Map();function visit(key){const st=state.get(key);if(st===1)return true;if(st===2)return false;state.set(key,1);for(const dep of by.get(key)?.src||[])if(by.has(dep)&&visit(dep))return true;state.set(key,2);return false}return items.some(i=>!state.get(i.k)&&visit(i.k))}

function saveItem(k,t){const g=x=>$('#m_'+x)?.value,i={k,t,n:g('n')||'Item',max:+g('max')||0};
 if(t=='att'){i.mode=g('mode');i.pen=+g('pen')||0;i.bandBasis=g('bandBasis')||'absent';i.bandRules=[...document.querySelectorAll('#bandRows .band-row')].map(row=>({op:row.querySelector('.band-op').value,n:+row.querySelector('.band-n').value||0,grade:+row.querySelector('.band-grade').value||0}));}
 if(t==='grp')i.preset=g('preset')||'custom';
 if(t=='grp'||t=='sum')i.src=[...document.querySelectorAll('#modal input[type=checkbox]:checked')].map(x=>x.value);
 if(t=='grp'){i.top=+g('top')||0;i.agg=g('agg');i.mul=g('mul')===''?1:+g('mul')}
 const it=S.cfg.items.slice(),x=it.findIndex(y=>y.k===k);x<0?it.push(i):it[x]=i;
 if(gradeItemDependencyCycle(it))return alert('These calculated grade sources create a circular dependency. Change the selected items.');
 if(i.t==='att'&&i.mode==='bands'&&i.bandRules.some(r=>r.grade<0||r.grade>i.max))return alert('Each attendance band grade must be between 0 and the maximum mark.');
 Cf().update({items:it}).then(()=>{$('#modal').innerHTML=''}).catch(e=>alert(e.message))}
function delItem(k){if(!confirm('Remove this item?'))return;Cf().update({items:S.cfg.items.filter(i=>i.k!==k).map(i=>i.src?{...i,src:i.src.filter(x=>x!==k)}:i)})}
/* Official university workbook borrowed from CourseTrack; preserves original formatting/formulas. */
const OFFICIAL_GRADE_TEMPLATE_B64='';

const CRS0={univ:'Galala University',prog:'PharmD-Clinical Pharmacy Program',sem:'FALL 2025-2026',code:'PPC101',name:'MEDICINAL PLANTS',ch:'3',inst:'Assoc. Prof. Dr. Reda Foad Abdelhameed'};
