const CL=[['univ','University'],['prog','Program'],['sem','Semester'],['code','Course code'],['name','Course name'],['ch','Credit hours'],['inst','Instructor name']];
const TC=[['mid','Midterm'],['cw','Class work (Quizzes + Project)'],['pr','Practical exam'],['fin','Final']];

function templateKeySources(key){const raw=(S.cfg.map||{})[key];return Array.isArray(raw)?raw.filter(Boolean):raw?[raw]:[]}
